// spec: specs/date-now.md 3.4 · кейс .qa/tests/date-now/DN-10.md
// free: шаринг выключается (предусловие и итог) → @data. «להפעיל עם שיתוף מיקום» не нажимается.
import { test, expect } from '@playwright/test';
import path from 'path';
import { disableSharing } from '../location-map/map-helpers';
import { saveSession } from '../_shared/session';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/free.json'),
  viewport: { width: 375, height: 629 },
  hasTouch: true,
  geolocation: { latitude: 32.0853, longitude: 34.7818, accuracy: 10 },
  permissions: ['geolocation'],
});

test.describe('דייט עכשיו — кнопка согласия на 375', () => {
  test('шаринг выключен: «להפעיל עם שיתוף מיקום» в 2 строки, не выходит за край шита и экрана 375 @iphone @data (#a5ce54)', async ({ page }) => {
    try {
      await disableSharing(page);
      const pill = page.getByTestId('date-now-pill');
      await pill.click();
      await expect(page.getByText('פנוי/ה לדייט עכשיו?')).toBeVisible();
      const cta = page.getByRole('button', { name: 'להפעיל עם שיתוף מיקום' });
      await expect(cta).toBeVisible();
      const m = await cta.evaluate((b) => {
        const r = b.getBoundingClientRect();
        // строки текста: высота текстового блока / межстрочный интервал
        const t = [...b.querySelectorAll('div')].find((d) => d.childElementCount === 0 && (d.textContent ?? '').includes('שיתוף')) ?? b;
        const tr = t.getBoundingClientRect();
        const lh = parseFloat(getComputedStyle(t).lineHeight) || 24;
        return { left: r.left, right: r.right, vw: window.innerWidth, lines: Math.round(tr.height / lh), overflow: t.scrollWidth - t.clientWidth };
      });
      // Р2: кнопка в 2 строки на 375, без выхода за край.
      expect(m.lines).toBe(2);
      expect(m.left).toBeGreaterThanOrEqual(0);
      expect(m.right).toBeLessThanOrEqual(m.vw);
      expect(m.overflow).toBeLessThanOrEqual(0);
      await page.getByRole('button', { name: 'לא עכשיו' }).click();
      await expect(page.getByText('שיתוף מיקום כבוי')).toBeVisible();
    } finally {
      await disableSharing(page).catch(() => {});
      await saveSession(page, 'free');
    }
  });
});
